package vn.cinema;
import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import vn.cinema.app.Application;import vn.cinema.service.CinemaService;import vn.cinema.dto.CinemaRequests.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(classes=Application.class)class CinemaTest{@Autowired CinemaService s;@Test void generateSeatsOnceAndEditSeat(){var c=s.saveCinema(null,new CinemaInput("Rạp thử","Địa chỉ","Hà Nội","0900000000","","","ACTIVE"));var r=s.saveRoom(null,new RoomInput(c.id,"Phòng 1",0,"STANDARD","ACTIVE"));var seats=s.generate(r.id,new Generate(8,8));assertThat(seats).hasSize(64);assertThat(s.room(r.id).totalSeats).isEqualTo(64);assertThatThrownBy(()->s.generate(r.id,new Generate(8,8))).hasMessageContaining("đã có ghế");assertThat(s.seat(seats.get(0).id,new SeatInput("VIP","LOCKED")).status).isEqualTo("LOCKED");}}
